import React, { useEffect, useRef, useState } from 'react';

interface MemeCanvasProps {
  imageSrc: string;
  caption: string;
}

export const MemeCanvas: React.FC<MemeCanvasProps> = ({ imageSrc, caption }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [downloadUrl, setDownloadUrl] = useState<string | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !imageSrc) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = imageSrc;

    img.onload = () => {
      // Set canvas size to match image
      canvas.width = img.width;
      canvas.height = img.height;

      // Draw Image
      ctx.drawImage(img, 0, 0);

      if (caption) {
        // Text Configuration
        // Using Noto Sans SC for that authentic East Asian subtitle feel, fallback to sans-serif
        const fontFamily = '"Noto Sans SC", "Hiragino Kaku Gothic ProN", "Noto Sans CJK SC", sans-serif';

        // Dynamic font size: roughly 8% of the image height
        const fontSize = Math.floor(canvas.height * 0.08); 
        ctx.font = `900 ${fontSize}px ${fontFamily}`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';

        // Position: Bottom center with some padding
        const x = canvas.width / 2;
        const y = canvas.height - (canvas.height * 0.05); // 5% padding from bottom

        // 1. Text Outline (Stroke)
        // To get a "thick black outline", we use strokeText with a thick lineWidth
        ctx.strokeStyle = 'black';
        ctx.lineWidth = fontSize * 0.15; // Stroke width relative to font size
        ctx.lineJoin = 'round'; // Smooth corners
        ctx.miterLimit = 2;
        ctx.strokeText(caption, x, y);

        // 2. Drop Shadow (Hard shadow for "Pop")
        // We actually simulate this better with the stroke, but let's add a subtle hard shadow
        // drawn BEFORE the main white text but usually stroke handles the readability best.
        // Let's stick to the stroke + fill as it's the standard meme/subtitle style.

        // 3. Text Fill
        ctx.fillStyle = 'white';
        ctx.fillText(caption, x, y);
      }

      // Generate download URL
      setDownloadUrl(canvas.toDataURL('image/png'));
    };
  }, [imageSrc, caption]);

  return (
    <div className="flex flex-col items-center w-full max-w-4xl">
      {/* Visual Display */}
      <div className="relative rounded-lg overflow-hidden shadow-2xl border-4 border-gray-800 bg-gray-900">
        <canvas 
          ref={canvasRef} 
          className="max-w-full h-auto max-h-[70vh] object-contain"
        />
      </div>

      {/* Action Buttons */}
      <div className="mt-6">
        {downloadUrl && (
          <a
            href={downloadUrl}
            download={`oogiri_meme_${Date.now()}.png`}
            className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md shadow-sm text-black bg-yellow-400 hover:bg-yellow-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-yellow-500 transition-all transform hover:scale-105"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
            保存大喜利图片
          </a>
        )}
      </div>
    </div>
  );
};

